// docs/02 — files go through a StorageProvider: local disk (dev) or S3-compatible (prod).
export interface StorageProvider {
  readonly driver: "local" | "s3" | "memory";
  put(key: string, body: Uint8Array, contentType: string): Promise<void>;
  /** null when the object does not exist. */
  get(key: string): Promise<Uint8Array | null>;
  /** Missing objects are ignored. */
  delete(key: string): Promise<void>;
}

/** Keys are generated by the app (`<userId>/<random>`); anything else is refused. */
export function assertSafeKey(key: string): void {
  if (!/^[a-f0-9]{24}\/[A-Za-z0-9_-]{8,64}$/.test(key)) throw new Error("Invalid storage key");
}

/** In-memory provider (tests). */
export function memoryStorage(): StorageProvider & { objects: Map<string, Uint8Array> } {
  const objects = new Map<string, Uint8Array>();
  return {
    driver: "memory",
    objects,
    async put(key, body) {
      assertSafeKey(key);
      objects.set(key, body);
    },
    async get(key) {
      return objects.get(key) ?? null;
    },
    async delete(key) {
      objects.delete(key);
    },
  };
}
